pragma solidity >=0.8.0;

contract Child {
    uint256 public wideHits;
    uint256 public narrowHits;
    uint256 public lastResult;

    function f(uint256 x) public returns (uint256) {
        wideHits = x + 1;
        return 200 + x;
    }

    function f(uint8 x) public returns (uint256) {
        narrowHits = uint256(x) + 1;
        return 100 + x;
    }

    function g(uint256 x) public returns (uint256) {
        lastResult = this.f(x);
        return lastResult;
    }
}
